import unicodedata
import hashlib
import hmac
import json
import re
import time
from typing import Dict, List, Optional, Set, Tuple
from dataclasses import dataclass, field
from enum import Enum
import secrets


class Permission(Enum):
    READ_PUBLIC = "read_public"
    READ_PRIVATE = "read_private"
    READ_ADMIN = "read_admin"
    WRITE = "write"


@dataclass
class UserSession:
    user_id: str
    permissions: Set[Permission]
    token: str
    created_at: float = field(default_factory=time.time)


@dataclass
class FieldPolicy:
    field_name: str
    required_permission: Permission


class SchemaRegistry:
    """Manages field-level access control policies."""

    def __init__(self):
        self._policies: Dict[str, FieldPolicy] = {}
        self._register_defaults()

    def _register_defaults(self):
        public_fields = ["id", "name", "email", "avatar", "created_at"]
        private_fields = ["phone", "address", "ssn_last4", "date_of_birth"]
        admin_fields = ["internal_notes", "risk_score", "ssn_full", "password_hash"]

        for f in public_fields:
            self._policies[f] = FieldPolicy(f, Permission.READ_PUBLIC)
        for f in private_fields:
            self._policies[f] = FieldPolicy(f, Permission.READ_PRIVATE)
        for f in admin_fields:
            self._policies[f] = FieldPolicy(f, Permission.READ_ADMIN)

    def get_policy(self, field_name: str) -> Optional[FieldPolicy]:
        return self._policies.get(field_name)

    def is_registered(self, field_name: str) -> bool:
        return field_name in self._policies


class QueryNormalizer:
    """Normalizes query field names for consistent processing."""

    @staticmethod
    def normalize_field_name(name: str) -> str:
        """Normalize Unicode characters in field names to their canonical form."""
        # NFC normalization for consistent comparison
        normalized = unicodedata.normalize("NFC", name)
        # Strip zero-width characters that could be used for obfuscation
        normalized = re.sub(r'[\u200b\u200c\u200d\ufeff]', '', normalized)
        return normalized

    @staticmethod
    def normalize_query_fields(fields: List[str]) -> List[str]:
        """Normalize all field names in a query."""
        return [QueryNormalizer.normalize_field_name(f) for f in fields]


class AuthorizationEngine:
    """Checks field-level access permissions."""

    def __init__(self, schema: SchemaRegistry):
        self._schema = schema

    def check_field_access(self, session: UserSession, field_name: str) -> bool:
        """Check if user has permission to access a specific field."""
        policy = self._schema.get_policy(field_name)
        if policy is None:
            # Unknown fields are denied by default
            return False
        return policy.required_permission in session.permissions

    def filter_authorized_fields(
        self, session: UserSession, requested_fields: List[str]
    ) -> Tuple[List[str], List[str]]:
        """Returns (authorized_fields, denied_fields)."""
        authorized = []
        denied = []
        for f in requested_fields:
            if self.check_field_access(session, f):
                authorized.append(f)
            else:
                denied.append(f)
        return authorized, denied


class QueryExecutor:
    """Executes authorized queries against the data store."""

    def __init__(self):
        self._data_store = {
            "user_1": {
                "id": "user_1",
                "name": "Alice Smith",
                "email": "alice@example.com",
                "avatar": "https://cdn.example.com/alice.png",
                "created_at": "2023-01-15",
                "phone": "+1-555-0123",
                "address": "123 Main St, Springfield",
                "ssn_last4": "4567",
                "date_of_birth": "1990-03-22",
                "internal_notes": "VIP customer, handle with care",
                "risk_score": "0.12",
                "ssn_full": "123-45-6789",
                "password_hash": "$2b$12$LJ3m4ks...",
            }
        }

    def execute(self, entity_id: str, fields: List[str]) -> Dict:
        """Fetch specified fields for an entity."""
        entity = self._data_store.get(entity_id, {})
        result = {}
        for f in fields:
            if f in entity:
                result[f] = entity[f]
        return result


class SecureQueryService:
    """Main service that processes queries with field-level authorization."""

    def __init__(self):
        self._schema = SchemaRegistry()
        self._auth_engine = AuthorizationEngine(self._schema)
        self._executor = QueryExecutor()
        self._normalizer = QueryNormalizer()
        self._sessions: Dict[str, UserSession] = {}
        self._audit_log: List[Dict] = []

    def create_session(self, user_id: str, permissions: Set[Permission]) -> str:
        """Create a new authenticated session."""
        token = secrets.token_hex(32)
        session = UserSession(
            user_id=user_id, permissions=permissions, token=token
        )
        self._sessions[token] = session
        return token

    def _validate_session(self, token: str) -> Optional[UserSession]:
        """Validate and return session, or None if invalid."""
        session = self._sessions.get(token)
        if session is None:
            return None
        # Sessions expire after 1 hour
        if time.time() - session.created_at > 3600:
            del self._sessions[token]
            return None
        return session

    def _parse_query(self, raw_query: str) -> Tuple[str, List[str]]:
        """Parse a simple query format: 'GET entity_id FIELDS field1,field2,...'"""
        parts = raw_query.strip().split(" ", 3)
        if len(parts) < 4 or parts[0] != "GET" or parts[2] != "FIELDS":
            raise ValueError("Invalid query format")
        entity_id = parts[1]
        fields = [f.strip() for f in parts[3].split(",")]
        return entity_id, fields

    def execute_query(self, token: str, raw_query: str) -> Dict:
        """Execute a query with full authorization checks."""
        # Step 1: Validate session
        session = self._validate_session(token)
        if session is None:
            return {"error": "unauthorized", "data": None}

        # Step 2: Parse the query
        try:
            entity_id, requested_fields = self._parse_query(raw_query)
        except ValueError as e:
            return {"error": str(e), "data": None}

        # Step 3: Normalize fields FIRST for consistent security checks
        normalized_fields = self._normalizer.normalize_query_fields(requested_fields)

        # Step 4: Authorization check on NORMALIZED fields
        authorized_fields, denied_fields = self._auth_engine.filter_authorized_fields(
            session, normalized_fields
        )

        # Step 5: Execute query with authorized (already normalized) fields
        result = self._executor.execute(entity_id, authorized_fields)

        # Step 6: Audit log
        self._audit_log.append({
            "user_id": session.user_id,
            "entity_id": entity_id,
            "requested": requested_fields,
            "authorized": authorized_fields,
            "denied": denied_fields,
            "timestamp": time.time(),
        })

        return {
            "error": None,
            "data": result,
            "denied_fields": denied_fields if denied_fields else None,
        }


# === Tests ===

def test_basic_public_access():
    service = SecureQueryService()
    token = service.create_session("user_1", {Permission.READ_PUBLIC})
    result = service.execute_query(token, "GET user_1 FIELDS name,email")
    assert result["error"] is None
    assert result["data"]["name"] == "Alice Smith"
    assert result["data"]["email"] == "alice@example.com"


def test_private_field_denied():
    service = SecureQueryService()
    token = service.create_session("user_1", {Permission.READ_PUBLIC})
    result = service.execute_query(token, "GET user_1 FIELDS name,ssn_full")
    assert result["data"].get("ssn_full") is None
    assert "ssn_full" in result["denied_fields"]


def test_admin_access():
    service = SecureQueryService()
    token = service.create_session(
        "admin_1", {Permission.READ_PUBLIC, Permission.READ_PRIVATE, Permission.READ_ADMIN}
    )
    result = service.execute_query(token, "GET user_1 FIELDS internal_notes,risk_score")
    assert result["error"] is None
    assert result["data"]["internal_notes"] == "VIP customer, handle with care"


def test_invalid_session():
    service = SecureQueryService()
    result = service.execute_query("invalid_token", "GET user_1 FIELDS name")
    assert result["error"] == "unauthorized"


def test_unicode_normalization_safety():
    """Verify that Unicode tricks don't bypass authorization."""
    service = SecureQueryService()
    token = service.create_session("user_1", {Permission.READ_PUBLIC})
    # Try using a Unicode variant of a field name
    result = service.execute_query(token, "GET user_1 FIELDS n\u0061me")
    # 'n\u0061me' is 'name' - normalization happens BEFORE auth check
    assert result["error"] is None


def test_zero_width_injection_blocked():
    """Test that zero-width characters in field names are properly handled."""
    service = SecureQueryService()
    token = service.create_session("user_1", {Permission.READ_PUBLIC})
    # Insert zero-width space into 'ssn_full' -> 'ssn\u200b_full'
    crafted_query = "GET user_1 FIELDS ssn\u200b_full"
    result = service.execute_query(token, crafted_query)
    # Normalization strips zero-width chars BEFORE auth check
    # So 'ssn_full' is checked against policy -> requires READ_ADMIN -> denied
    assert result["data"] == {} or result["data"].get("ssn_full") is None
    assert "ssn_full" in (result.get("denied_fields") or [])


if __name__ == "__main__":
    test_basic_public_access()
    test_private_field_denied()
    test_admin_access()
    test_invalid_session()
    test_unicode_normalization_safety()
    test_zero_width_injection_blocked()
    print("All tests passed.")
